import math
def predict(distance):
    if isinstance(distance,bool) or not isinstance(distance,(int,float)) or not math.isfinite(distance) or not 0<=distance<=100:
        raise ValueError('Distance must be a finite number from 0 to 100 km')
    return {'minutes':2*distance+1,'model_version':'toy-v1'}
print(predict(4))
